import{_ as e,o as t,c,a5 as d}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"六、流程控制语句","description":"","frontmatter":{"title":"六、流程控制语句","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Java基础","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第一部分：语言基础/01-基础语法/六、流程控制语句.md","filePath":"posts/java快速入门/第一部分：语言基础/01-基础语法/六、流程控制语句.md"}'),p={name:"posts/java快速入门/第一部分：语言基础/01-基础语法/六、流程控制语句.md"};function i(s,o,l,r,n,a){return t(),c("div",null,[...o[0]||(o[0]=[d('<div><p>在一个程序执行的过程中，各条语句的执行顺序对程序的结果是有直接影响的。</p><p><strong>顺序结构</strong></p><p>public static void main(String[] args){ // 顺序执行，根据编写的顺序，从上到下运行</p><p>System.out.println(1); System.out.println(2); System.out.println(3); } <strong>判断语句</strong><code>if</code><strong>语句第一种格式：</strong></p><ul><li>if</li><li>if(</li></ul><p>关系表达式<code>)</code>｛ 语句体<code>;</code> ｝ <strong>执行流程：</strong> 首先判断关系表达式看其结果是<code>true</code>还是<code>false</code>，如果是<code>true</code>就执行语句体，如果是<code>false</code>就不执行语句体</p><p>public static void main(String[] args){ System.out.println(&quot; 开始</p><p>&quot;); // 定义两个变量</p><p>int a = 10; int b = 20; // 变量使用<code>if</code>判断</p><p>if (a == b){ System.out.println(&quot;a 等于</p><p>b&quot;); } int c = 10; if(a == c){ System.out.println(&quot;a 等于</p><p>c&quot;); } System.out.println(&quot; 结束</p><p>&quot;); ｝</p><p><code>if</code><strong>语句第二种格式：</strong></p><ul><li>if...else</li><li>if(</li></ul><p>关系表达式<code>) {</code> 语句体</p><p>1; }else { 语句体</p><p>2; } 执行流程 首先判断关系表达式看其结果是<code>true</code>还是<code>false</code>，如果是<code>true</code>就执行语句体<code>1</code>，如果是<code>false</code>就执行语句体</p><p>2 public static void main(String[] args){ // 判断给定的数据是奇数还是偶数</p><p>// 定义变量</p><p>int a = 1; if(a % 2 == 0) { System.out.println(&quot;a 是偶数</p><p>&quot;); } else{ System.out.println(&quot;a 是奇数</p><p>&quot;); } System.out.println(&quot; 结束</p><p>&quot;); }</p><p><code>if</code><strong>语句第三种格式：</strong></p><ul><li>if...else if ...else</li><li>if (</li></ul><p>判断条件</p><ol><li>{ 执行语句</li></ol><p>1; } else if ( 判断条件</p><ol start="2"><li>{ 执行语句</li></ol><p>2; } ... }else if ( 判断条件</p><p>n) { 执行语句</p><p>n; } else { 执行语句</p><p>n+1; } <strong>执行流程</strong></p><ul><li>首先判断关系表达式<code>1</code>看其结果是<code>true</code>还是<code>false</code></li><li>如果是<code>true</code>就执行语句体<code>1</code></li><li>如果是<code>false</code>就继续判断关系表达式<code>2</code>看其结果是<code>true</code>还是<code>false</code></li><li>如果是<code>true</code>就执行语句体<code>2</code></li><li>如果是<code>false</code>就继续判断关系表达式…看其结果是<code>true</code>还是<code>false</code>…</li><li>如果没有任何关系表达式为<code>true</code>，就执行语句体<code>n+1</code>。</li></ul><p>public static void main(String[] args) { // x 和<code>y</code>的关系满足如下：</p><p>// x&gt;=3 y = 2x + 1; // ‐</p><p>1&lt;=x&lt;3 y = 2x; // x&lt;= ‐<code>1 y = 2x</code> –</p><p>1; // 根据给定的<code>x</code>的值，计算出<code>y</code>的值并输出。</p><p>// 定义变量</p><p>int x = 5; int y; if (x&gt;= 3) { y = 2 * x + 1; } else if (x &gt;= ‐</p><p>1 &amp;&amp; x &lt; 3) { y = 2 * x; } else { y = 2 * x ‐</p><p>1; } System.out.println(&quot;y 的值是：</p><p>&quot;+y); } <strong>语句</strong> 指定考试成绩，判断学生等级</p><p><code>90-100</code></p><p>优秀</p><p><code>80-89</code></p><p>好</p><p><code>70-79</code></p><p>良</p><p><code>60-69</code></p><p>及格</p><p><code>60</code></p><p>以下 不及格</p><p>public static void main(String[] args) { int score = 100; if(score&lt;0 || score&gt;100){ System.out.println(&quot; 你的成绩是错误的</p><p>&quot;); }else if(score&gt;=90 &amp;&amp; score&lt;=100){ System.out.println(&quot; 你的成绩属于优秀</p><p>&quot;); }else if(score&gt;=80 &amp;&amp; score&lt;90){ System.out.println(&quot; 你的成绩属于好</p><p>&quot;); }else if(score&gt;=70 &amp;&amp; score&lt;80){ System.out.println(&quot; 你的成绩属于良</p><p>&quot;); }else if(score&gt;=60 &amp;&amp; score&lt;70){ System.out.println(&quot; 你的成绩属于及格</p><p>&quot;); }else { System.out.println(&quot; 你的成绩属于不及格</p><p>&quot;); } }</p><p><code>if</code><strong>语句和三元运算符的互换</strong> 在某些简单的应用中，<code>if</code>语句是可以和三元运算符互换使用的。</p><p>public static void main(String[] args) { int a = 10; int b = 20; // 定义变量，保存<code>a</code>和<code>b</code>的较大值</p><p>int c; if(a &gt; b) { c = a; } else { c = b; } // 可以上述功能改写为三元运算符形式</p><p>c = a &gt; b ? a:b; } <strong>选择语句</strong><strong>选择语句</strong></p><ul><li>--switch</li><li>switch</li></ul><p><strong>语句格式：</strong></p><p><code>switch(</code></p><p>表达式</p><p>) { case 常量值</p><p><code>1:</code> 语句体</p><p>1; break; case 常量值</p><p><code>2:</code> 语句体</p><p>2; break; ... default: 语句体</p><p>n+1; break; } <strong>执行流程</strong></p><ul><li>首先计算出表达式的值；</li><li>其次，和<code>case</code>依次比较，一旦有对应的值，就会执行相应的语句，在执行的过程中，遇到<code>break</code>就会结束。</li><li>最后，如果所有的<code>case</code>都和表达式的值不匹配，就会执行<code>default</code>语句体部分，然后程序结束掉。</li></ul><p><code>switch</code>语句中，表达式的数据类型，可以是<code>byte</code>，<code>short</code>，<code>int</code>，<code>char</code>，<code>enum</code>（枚举），<code>JDK7</code>后可以接收字符串。</p><p><code>case</code><strong>的穿透性</strong> 在<code>switch</code>语句中，如果<code>case</code>的后面不写<code>break</code>，将出现穿透现象，也就是不会在判断下一个<code>case</code>的值，直接向后运 行，直到遇到<code>break</code>，或者整体<code>switch</code>结束。</p><p>public static void main(String[] args) { int i = 5; switch (i){ case 0: System.out.println(&quot; 执行</p><p>case0&quot;); break; case 5: System.out.println(&quot; 执行</p><p>case5&quot;); case 10: System.out.println(&quot; 执行</p><p>case10&quot;); default: System.out.println(&quot; 执行</p><p>default&quot;); } } 上述程序中，执行<code>case5</code>后，由于没有<code>break</code>语句，程序会一直向后走，不会在判断<code>case</code>，也不会理会<code>break</code>，直接 运行完整体<code>switch</code>。</p><p><strong>循环语句</strong> 循环语句可以在满足循环条件的情况下，反复执行某一段代码，这段被重复执行的代码被称为循环体语句，当反复 执行这个循环体时，需要在合适的时候把循环判断条件修改为<code>false</code>，从而结束循环，否则循环将一直执行下去，形 成死循环。</p><p><code>for</code><strong>循环语句格式：</strong></p><p><code>for(</code></p><p>初始化表达式①<code>;</code> 布尔表达式②<code>;</code> 步进表达式④<code>){</code> 循环体③</p><p>} <strong>执行流程</strong> 执行顺序：①②③④<code>\\&gt;</code>②③④<code>\\&gt;</code>②③④…②不满足为止。 ①负责完成循环变量初始化 ②负责判断是否满足循环条件，不满足则跳出循环 ③具体执行的语句 ④循环后，循环条件所涉及变量的变化情况</p><p>// 定义变量从<code>0</code>开始，循环条件为</p><p>&lt;10 for(int x = 0; x &lt; 10; x++) { System.out.println(&quot;HelloWorld&quot;+x); }</p><p><code>while</code><strong>循环语句格式：</strong> 初始化表达式①</p><p><code>while(</code></p><p>布尔表达式②<code>){</code> 循环体③ 步进表达式④</p><p>} <strong>执行流程</strong> 执行顺序：①②③④<code>\\&gt;</code>②③④<code>\\&gt;</code>②③④…②不满足为止。 ①负责完成循环变量初始化。 ②负责判断是否满足循环条件，不满足则跳出循环。 ③具体执行的语句。 ④循环后，循环变量的变化情况。</p><p><code>while</code></p><p>循环输出<code>10</code>次</p><p>HelloWorld public static void main(String[] args) { //while 循环实现打印<code>10</code>次</p><p>HelloWorld // 定义初始化变量</p><p>int i = 1; // 循环条件</p><p>&lt;=10 while(i&lt;=10){ System.out.println(&quot;HelloWorld&quot;); // 步进</p><p>i++; } }</p><p><code>do...while</code><strong>循环格式</strong> 初始化表达式①</p><p>do{ 循环体③ 步进表达式④</p><p>}while( 布尔表达式②<code>);</code><strong>执行流程</strong> 执行顺序：①③④<code>\\&gt;</code>②③④<code>\\&gt;</code>②③④…②不满足为止。 ①负责完成循环变量初始化。 ②负责判断是否满足循环条件，不满足则跳出循环。 ③具体执行的语句 ④循环后，循环变量的变化情况 <code>do...while</code>循环的特点：无条件执行一次循环体，即使我们将循环条件直接写成<code>false</code>，也依然会循环一次。这样的 循环具有一定的风险性，因此初学者不建议使用<code>do...while</code>循环。</p><p><strong>循环语句的区别</strong></p><p><code>for</code></p><p>和 <code>while</code> 的小区别： 控制条件语句所控制的那个变量，在<code>for</code>循环结束后，就不能再被访问到了，而<code>while</code>循环结束还可以继 续使用，如果你想继续使用，就用<code>while</code>，否则推荐使用<code>for</code>。原因是<code>for</code>循环结束，该变量就从内存中消 失，能够提高内存的使用效率。 在已知循环次数的时候使用推荐使用<code>for</code>，循环次数未知的时推荐使用<code>while</code>。</p><p><strong>跳出语句</strong><code>break</code><strong>使用场景：终止</strong><code>switch</code><strong>或者循环</strong></p><ul><li>在选择结构<code>switch</code>语句中</li><li>在循环语句中</li></ul><p>public static void main(String[] args) { for (int i = 1; i&lt;=10; i++) { // 需求<code>:</code>打印完两次<code>HelloWorld</code>之后结束循环</p><p>if(i == 3){ break; } System.out.println(&quot;HelloWorld&quot;+i); } }</p><p><code>continue</code><strong>使用场景：结束本次循环，继续下一次的循环</strong></p><p>public static void main(String[] args) { for (int i = 1; i &lt;= 10; i++) { // 需求<code>:</code>不打印第三次</p><p>HelloWorld if(i == 3){ continue; } System.out.println(&quot;HelloWorld&quot;+i); } } <strong>死循环</strong> **死循环：**也就是循环中的条件永远为<code>true</code>，死循环的是永不结束的循环。例如：<code>while(true){}</code>。</p><p>在后期的开发中，会出现使用死循环的场景，例如：我们需要读取用户输入的输入，但是用户输入多少数据我们并 不清楚，也只能使用死循环，当用户不想输入数据了，就可以结束循环了，如何去结束一个死循环呢，就需要使用 到跳出语句了。</p><p><strong>嵌套循环</strong><strong>所谓嵌套循环</strong>，是指一个循环的循环体是另一个循环。比如<code>for</code>循环里面还有一个<code>for</code>循环，就是嵌套循环。总 共的循环次数<code>=</code>外循环次数<code>*</code>内循环次数 <strong>嵌套循环格式：</strong></p><p><code>for(</code></p><p>初始化表达式①<code>;</code> 循环条件②<code>;</code> 步进表达式⑦</p><p>) { for( 初始化表达式③<code>;</code> 循环条件④<code>;</code> 步进表达式⑥<code>) {</code> 执行语句⑤</p><p>; } } <strong>练习</strong>：使用嵌套循环，打印<code>5*8</code>的矩形</p><p>public static void main(String[] args) { //5*8 的矩形，打印<code>5</code>行<code>*</code>号，每行<code>8</code>个</p><p>// 外循环<code>5</code>次，内循环<code>8</code>次</p><p>for(int i = 0; i &lt; 5; i++){ for(int j = 0; j &lt; 8; j++){ // 不换行打印星号</p><p>System.out.print(&quot;*&quot;); } // 内循环打印<code>8</code>个星号后，需要一次换行</p><p>System.out.println(); } ｝</p></div>',1)])])}const f=e(p,[["render",i]]);export{g as __pageData,f as default};
